import * as React from "react";
import { cn } from "cn";
import { DropdownMenu as DropdownMenuPrimitive } from "radix-ui";

import { useV4PortalContainer } from "../scope";

import { Icon } from "./icon";
import { menuRowContent, menuShortcutContent } from "./menu-content";

import menu from "./menu.module.css";

function DropdownMenu({ ...props }: React.ComponentProps<typeof DropdownMenuPrimitive.Root>) {
  return <DropdownMenuPrimitive.Root data-slot="dropdown-menu" {...props} />;
}

function DropdownMenuPortal({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Portal>) {
  return (
    <DropdownMenuPrimitive.Portal
      container={useV4PortalContainer()}
      data-slot="dropdown-menu-portal"
      {...props}
    />
  );
}

const DropdownMenuTrigger = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Trigger>
>(({ ...props }, ref) => {
  return <DropdownMenuPrimitive.Trigger ref={ref} data-slot="dropdown-menu-trigger" {...props} />;
});
DropdownMenuTrigger.displayName = "DropdownMenuTrigger";

const DropdownMenuContent = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Content>
>(({ className, collisionPadding = 8, align = "start", sideOffset = 4, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.Portal container={useV4PortalContainer()}>
      <DropdownMenuPrimitive.Content
        ref={ref}
        data-slot="dropdown-menu-content"
        collisionPadding={collisionPadding}
        sideOffset={sideOffset}
        align={align}
        className={cn("z-50", menu.surface, menu.panel, menu.inset, menu.motion, className)}
        {...props}
      />
    </DropdownMenuPrimitive.Portal>
  );
});
DropdownMenuContent.displayName = "DropdownMenuContent";

const DropdownMenuGroup = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Group>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Group>
>(({ ...props }, ref) => {
  return <DropdownMenuPrimitive.Group ref={ref} data-slot="dropdown-menu-group" {...props} />;
});
DropdownMenuGroup.displayName = "DropdownMenuGroup";

const DropdownMenuItem = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Item> & {
    inset?: boolean;
    variant?: "default" | "destructive";
  }
>(({ className, inset, variant = "default", children, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.Item
      ref={ref}
      data-slot="dropdown-menu-item"
      data-inset={inset}
      data-variant={variant}
      className={cn(menu.row, className)}
      {...props}
    >
      {menuRowContent(children)}
    </DropdownMenuPrimitive.Item>
  );
});
DropdownMenuItem.displayName = "DropdownMenuItem";

const DropdownMenuCheckboxItem = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.CheckboxItem>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.CheckboxItem> & {
    closeOnSelect?: boolean;
  } & {
    inset?: boolean;
  }
>(({ className, children, checked, inset, onSelect, closeOnSelect = false, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.CheckboxItem
      ref={ref}
      data-slot="dropdown-menu-checkbox-item"
      data-inset={inset}
      className={cn(menu.row, className)}
      checked={checked}
      {...props}
      onSelect={(event) => {
        onSelect?.(event);
        if (!closeOnSelect) event.preventDefault();
      }}
    >
      <span className={menu.indicator} data-slot="dropdown-menu-checkbox-item-indicator">
        <DropdownMenuPrimitive.ItemIndicator>
          <Icon name="check" />
        </DropdownMenuPrimitive.ItemIndicator>
      </span>
      {menuRowContent(children)}
    </DropdownMenuPrimitive.CheckboxItem>
  );
});
DropdownMenuCheckboxItem.displayName = "DropdownMenuCheckboxItem";

const DropdownMenuRadioGroup = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.RadioGroup>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.RadioGroup>
>(({ ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.RadioGroup ref={ref} data-slot="dropdown-menu-radio-group" {...props} />
  );
});
DropdownMenuRadioGroup.displayName = "DropdownMenuRadioGroup";

const DropdownMenuRadioItem = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.RadioItem>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.RadioItem> & {
    closeOnSelect?: boolean;
  } & {
    inset?: boolean;
  }
>(({ className, children, inset, onSelect, closeOnSelect = false, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.RadioItem
      ref={ref}
      data-slot="dropdown-menu-radio-item"
      data-inset={inset}
      className={cn(menu.row, className)}
      {...props}
      onSelect={(event) => {
        onSelect?.(event);
        if (!closeOnSelect) event.preventDefault();
      }}
    >
      <span className={menu.indicator} data-slot="dropdown-menu-radio-item-indicator">
        <DropdownMenuPrimitive.ItemIndicator>
          <Icon name="check" />
        </DropdownMenuPrimitive.ItemIndicator>
      </span>
      {menuRowContent(children)}
    </DropdownMenuPrimitive.RadioItem>
  );
});
DropdownMenuRadioItem.displayName = "DropdownMenuRadioItem";

const DropdownMenuLabel = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Label>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Label> & {
    inset?: boolean;
  }
>(({ className, inset, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.Label
      ref={ref}
      data-slot="dropdown-menu-label"
      data-inset={inset}
      className={cn(menu.label, className)}
      {...props}
    />
  );
});
DropdownMenuLabel.displayName = "DropdownMenuLabel";

const DropdownMenuSeparator = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Separator>
>(({ className, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.Separator
      ref={ref}
      data-slot="dropdown-menu-separator"
      className={cn(menu.separator, className)}
      {...props}
    />
  );
});
DropdownMenuSeparator.displayName = "DropdownMenuSeparator";

const DropdownMenuShortcut = React.forwardRef<
  React.ComponentRef<"span">,
  React.ComponentPropsWithoutRef<"span">
>(({ className, children, ...props }, ref) => {
  return (
    <span
      ref={ref}
      data-slot="dropdown-menu-shortcut"
      className={cn(menu.shortcut, className)}
      {...props}
    >
      {menuShortcutContent(children)}
    </span>
  );
});
DropdownMenuShortcut.displayName = "DropdownMenuShortcut";

function DropdownMenuSub({ ...props }: React.ComponentProps<typeof DropdownMenuPrimitive.Sub>) {
  return <DropdownMenuPrimitive.Sub data-slot="dropdown-menu-sub" {...props} />;
}

const DropdownMenuSubTrigger = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.SubTrigger>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.SubTrigger> & {
    inset?: boolean;
  }
>(({ className, inset, children, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.SubTrigger
      ref={ref}
      data-slot="dropdown-menu-sub-trigger"
      data-inset={inset}
      className={cn(menu.row, className)}
      {...props}
    >
      {menuRowContent(children)}
      <Icon name="chev-right" className={menu.trail} />
    </DropdownMenuPrimitive.SubTrigger>
  );
});
DropdownMenuSubTrigger.displayName = "DropdownMenuSubTrigger";

const DropdownMenuSubContent = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.SubContent>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.SubContent>
>(({ className, collisionPadding = 8, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.SubContent
      ref={ref}
      data-slot="dropdown-menu-sub-content"
      collisionPadding={collisionPadding}
      className={cn("z-50", menu.surface, menu.panel, menu.sub, menu.inset, menu.motion, className)}
      {...props}
    />
  );
});
DropdownMenuSubContent.displayName = "DropdownMenuSubContent";

export {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuPortal,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger
};

.surface {
  box-sizing: border-box;
  border-radius: calc(var(--v4-radius-pop) * var(--corners));
  background-color: var(--v4-pop);
  color: var(--v4-ink);
  box-shadow:
    0 0 0 var(--v4-size-control-border) var(--v4-pop-line),
    var(--v4-shadow-pop);
  outline: none;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
}
.panel {
  min-width: min(
    max(var(--v4-size-menu-min), var(--radix-popper-anchor-width, 0px)),
    var(--radix-popper-available-width, 100vw)
  );
  max-width: min(
    var(--v4-size-menu-max),
    var(--radix-popper-available-width, calc(100vw - 2 * var(--v4-space-16)))
  );
  max-height: var(--radix-popper-available-height, none);
  overflow-x: hidden;
  overflow-y: auto;
}
.sub {
  min-width: var(--v4-size-menu-min);
}
.card {
  display: flex;
  flex-direction: column;
  gap: var(--v4-space-8);
  width: min(var(--v4-size-popover), var(--radix-popper-available-width, 100vw));
  max-height: var(--radix-popper-available-height, none);
  overflow-y: auto;
  padding: var(--v4-space-12);
}
.tooltip {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: var(--v4-space-8);
  width: fit-content;
  max-width: min(var(--v4-size-menu-max), var(--radix-popper-available-width, 100vw));
  padding: var(--v4-space-6) var(--v4-space-8);
  border-radius: calc(var(--v4-radius-sm) * var(--corners));
  background-color: var(--v4-ink);
  color: var(--v4-on-ink);
  box-shadow: var(--v4-shadow-pop);
  overflow-wrap: break-word;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.tooltip:has([data-slot="kbd"]) {
  padding-inline-end: var(--v4-space-6);
}
.tooltipArrow {
  fill: var(--v4-ink);
}

.motion {
  --v4-pop-from: 0 0;
  transform-origin: var(--radix-popper-transform-origin, center);
}
.motion[data-side="bottom"] {
  --v4-pop-from: 0 calc(-1 * var(--v4-space-4));
}
.motion[data-side="top"] {
  --v4-pop-from: 0 var(--v4-space-4);
}
.motion[data-side="right"] {
  --v4-pop-from: calc(-1 * var(--v4-space-4)) 0;
}
.motion[data-side="left"] {
  --v4-pop-from: var(--v4-space-4) 0;
}
.motion:is([data-state="open"], [data-state="delayed-open"], [data-state="instant-open"]) {
  animation: popIn var(--v4-duration-fast) var(--v4-ease-spring) both;
}
.motion[data-state="closed"] {
  animation: popOut var(--v4-duration-exit-fast) var(--v4-ease-exit) both;
}
.tooltip.motion:is([data-state="open"], [data-state="delayed-open"], [data-state="instant-open"]) {
  animation-name: tipIn;
}
.tooltip.motion[data-state="closed"] {
  animation-name: tipOut;
}
@keyframes popIn {
  from {
    opacity: 0;
    translate: var(--v4-pop-from);
    scale: 1 0.96;
  }
}
@keyframes popOut {
  to {
    opacity: 0;
    translate: var(--v4-pop-from);
    scale: 1 0.96;
  }
}
@keyframes tipIn {
  from {
    opacity: 0;
    translate: var(--v4-pop-from);
  }
}
@keyframes tipOut {
  to {
    opacity: 0;
    translate: var(--v4-pop-from);
  }
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
}
@keyframes fadeOut {
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .motion:is([data-state="open"], [data-state="delayed-open"], [data-state="instant-open"]),
  .tooltip.motion:is(
      [data-state="open"],
      [data-state="delayed-open"],
      [data-state="instant-open"]
    ) {
    animation-name: fadeIn;
  }
  .motion[data-state="closed"],
  .tooltip.motion[data-state="closed"] {
    animation-name: fadeOut;
  }
}

.inset {
  --v4-menu-icon-slot: 0px;
  padding: var(--v4-space-4);
}
.inset:has(.row > :is(svg, [data-menu-icon]):not(.trail), .row[data-inset], .label[data-inset]) {
  --v4-menu-icon-slot: calc(var(--v4-size-icon) + var(--v4-space-8));
}

.list {
  max-height: calc(9 * var(--v4-size-control-sm));
  overflow-x: hidden;
  overflow-y: auto;
  outline: none;
  scroll-padding-block: var(--v4-space-4);
}

.row {
  position: relative;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  min-width: 0;
  min-height: var(--v4-size-control-sm);
  padding: var(--v4-space-6) var(--v4-space-8);
  padding-inline-start: calc(var(--v4-space-8) + var(--v4-menu-icon-slot, 0px));
  border-radius: calc(var(--v4-radius-sm) * var(--corners));
  overflow: hidden;
  color: var(--v4-ink);
  white-space: nowrap;
  cursor: default;
  user-select: none;
  outline: none;
  text-decoration: none;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
}
.row:has(> :is(svg, [data-menu-icon]):not(.trail)) {
  padding-inline-start: var(--v4-space-8);
}
.row > svg,
.row > [data-menu-icon] {
  flex: none;
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
  pointer-events: none;
}
.row:is(
    [data-highlighted],
    [data-selected="true"],
    [data-active],
    [data-state="open"],
    a:hover,
    a:focus-visible
  ) {
  background-color: var(--v4-select);
}
.row:is([data-variant="destructive"], [data-danger]) {
  color: var(--v4-bad);
}
.row:is([data-variant="destructive"], [data-danger]):is(
    [data-highlighted],
    [data-selected="true"]
  ) {
  background-color: var(--v4-action-danger-surface);
}
.row:is([data-disabled]:not([data-disabled="false"]), [aria-disabled="true"]) {
  color: var(--v4-faint);
  background-color: transparent;
  pointer-events: none;
}
.indicator {
  order: 1;
  display: flex;
  flex: none;
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
  align-items: center;
  justify-content: center;
  margin-inline-start: auto;
  pointer-events: none;
}
.indicator > svg {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
}
.indicator ~ :is(.shortcut, .meta) {
  margin-inline-start: 0;
}
.row:not([data-checked="true"]) > .indicator[data-command] {
  visibility: hidden;
}
.text {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-width: 0;
}
.title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.description {
  min-width: 0;
  overflow: hidden;
  color: var(--v4-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.shortcut,
.meta {
  order: 2;
  margin-inline-start: auto;
  padding-inline-start: var(--v4-space-8);
  color: var(--v4-muted);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.shortcut {
  display: inline-flex;
  flex: none;
  align-items: center;
}
.meta {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 45%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.meta + .shortcut {
  margin-inline-start: 0;
}
.trail {
  order: 3;
  flex: none;
  margin-inline-start: auto;
  color: var(--v4-muted);
}
.label,
.group > [cmdk-group-heading] {
  display: block;
  padding: var(--v4-space-6) var(--v4-space-8);
  padding-inline-start: calc(var(--v4-space-8) + var(--v4-menu-icon-slot, 0px));
  color: var(--v4-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.label:not(:first-child, .separator + *),
:is([role="group"], [cmdk-group]):not(:first-child)
  > :is(.label, [cmdk-group-heading]):first-child {
  margin-top: var(--v4-space-4);
  padding-top: calc(var(--v4-space-6) + var(--v4-space-4));
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.separator {
  height: var(--v4-size-control-border);
  margin: var(--v4-space-4) 0;
  border: 0;
  background-color: var(--v4-line-soft);
}
.empty {
  padding: var(--v4-space-16) var(--v4-space-8);
  color: var(--v4-muted);
  text-align: center;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--v4-space-4);
  padding: var(--v4-space-4);
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.hints {
  container-type: inline-size;
  display: flex;
  align-items: center;
  gap: var(--v4-space-12);
  min-height: var(--v4-size-control-sm);
  padding: var(--v4-space-4) var(--v4-space-12);
  overflow: hidden;
  border-top: var(--v4-size-control-border) solid var(--v4-line-soft);
  color: var(--v4-muted);
  white-space: nowrap;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.hint {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--v4-space-4);
}
.hintsExtra {
  min-width: 0;
  margin-inline-start: auto;
  overflow: hidden;
  text-overflow: ellipsis;
}
@container (max-width: 360px) {
  .hint:nth-child(n + 2) {
    display: none;
  }
}
@container (max-width: 200px) {
  .hint {
    display: none;
  }
}

.navItem {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--v4-space-control-gap);
  box-sizing: border-box;
  min-height: var(--v4-size-control-sm);
  padding: var(--v4-space-6) var(--v4-space-control-inline-sm);
  border-radius: calc(var(--v4-radius-control) * var(--corners));
  background-color: transparent;
  color: var(--v4-ink);
  white-space: nowrap;
  text-decoration: none;
  transition-property: background-color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
  font-family: var(--v4-type-label-font-family);
  font-size: var(--v4-type-label-font-size);
  line-height: var(--v4-type-label-line-height);
  font-weight: var(--v4-type-label-font-weight);
  letter-spacing: var(--v4-type-label-letter-spacing);
}
.navItem:is(:hover, [data-state="open"], [data-active]) {
  background-color: var(--v4-select);
}
.navItem:disabled {
  opacity: 0.5;
  pointer-events: none;
}
.navChevron {
  width: var(--v4-size-icon-xs);
  height: var(--v4-size-icon-xs);
  transition-property: rotate;
  transition-duration: var(--v4-duration-moderate);
  transition-timing-function: var(--v4-ease-standard);
}
.navItem[data-state="open"] > .navChevron {
  rotate: 180deg;
}
.navViewportAnchor {
  position: absolute;
  top: 100%;
  left: 0;
  z-index: 50;
  display: flex;
  padding-top: var(--v4-space-4);
  translate: var(--v4-nav-viewport-x, 0) 0;
}
.navViewportAnchor[data-placed] {
  transition-property: translate;
  transition-duration: var(--v4-duration-moderate);
  transition-timing-function: var(--v4-ease-standard);
}
.navViewport {
  position: relative;
  overflow: hidden;
  width: var(--radix-navigation-menu-viewport-width);
  height: var(--radix-navigation-menu-viewport-height);
  max-width: min(calc(100vw - 2 * var(--v4-space-16)), var(--v4-size-measure-form));
  transform-origin: top left;
}
.navContent {
